"""Competing-request scheduling and read-only quantity counterfactuals."""
COORD_STYLE=r'''
.coordorder{display:flex;gap:9px;flex-wrap:wrap;margin:18px 0}.coordstep{border:1px solid var(--line);border-radius:11px;padding:10px 13px;max-width:260px;overflow-wrap:anywhere}.coordstep.wait{opacity:.65;border-style:dashed}.coordpreview{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin:16px 0}.coordpreview label{flex:1;min-width:140px}.coordpreview select,.coordpreview input{display:block;width:100%;margin-top:6px}.coordpreview input{padding:9px}.coordowner{font-weight:600}.coordtimeline{max-height:500px;overflow:auto}.coordfacts{font-variant-numeric:tabular-nums}
'''
COORD_SCRIPT=r'''
let coordinationTimer=null,coordinationData=null,coordinationHandledJob=null;
function coordinationOptions(kind){return (catalog.runs[kind]||[]).map(r=>`<option value="${esc(r.id)}" ${selected[kind]===r.id?"selected":""}>${esc(stamp(r.id))} · ${esc(human(r.summary.status))}</option>`).join("");}
const coordinationBusy=()=>["RUNNING","QUEUED"].includes(catalog.lab?.job?.status);
function coordinationJob(){const j=catalog.lab?.job;return j?`<div class="callout ${["FAILED","STOPPED"].includes(j.status)?"warning":""}"><strong>${esc(human(j.status))}</strong> · ${esc(human(j.kind))}${j.error?`<p>${esc(j.error)}</p>`:""}${j.log?evidence("Runner log",j.log):""}</div>`:"";}
function coordinationPaint(data){
 const s=data.summary,p=s.plans.at(-1),choice=p?.choice,compare=p?.comparison;coordinationData=data;
 if(!p){$("#coordbody").innerHTML='<div class="empty"><h2>Collecting requests</h2><p>No approved execution plan is recorded yet.</p></div>';return;}
 const initial=p.basis.state,completed=s.coordination_events.find(e=>e.kind==="BATCH_COMPLETED"&&e.plan_id===p.id),recovery=s.policy_snapshot.events.filter(e=>e.kind==="RECOVERY_REPORT").at(-1)?.report;
 const owners={A:"Deployment A",B:"Cost B",C:"Traffic C"},byId=Object.fromEntries(s.intents.map(i=>[i.id,i])),selectedIds=new Set(choice.accepted),reserved=Object.values(initial.reservations).filter(r=>r.status==="PENDING").reduce((n,r)=>n+r.units,0),before=initial.stable_units+Object.values(initial.deployments).reduce((n,d)=>n+d.allocated_units,0)+reserved;
 $("#coordbody").innerHTML=`<div class="pillrow">${badge(s.mode,"info")}${badge(human(p.status),p.status==="COMPLETED"?"good":"warn")}${badge(s.lifecycle==="STOPPED"?"Workers stopped after outcome":s.lease_elapsed?"Lease elapsed · inspect status":"Saved leased-worker observation","info")}</div>${s.historical_source?'<div class="callout warning">Historical coordinator source. Inspect this record with its pinned source before recomputing it.</div>':""}<div class="grid g4">${metric("Requests selected",`${choice.accepted.length} / ${s.intents.length}`,`${choice.waiting.length} wait with an explanation`)}${metric("Priority score",choice.objective[0],`FIFO ${compare.fifo.objective[0]} · ${compare.orders_compared} orders compared`)}${metric("Exact execution",completed?.metrics?.committed??"Pending",`Planned ${choice.committed_units} / ${choice.capacity_limit} units`)}${metric("Current saved recovery",recovery?human(recovery.status):"Not requested",`A ${s.policy_snapshot.state.paused_runs.includes("deploy-A")?"paused":"active"}`)}</div><div class="card"><h2>Reviewed execution order</h2><p class="small">${esc(p.origin)}. ${esc(compare.objective_policy)}</p><div class="coordorder">${choice.order.map((id,i)=>`<div class="coordstep ${selectedIds.has(id)?"":"wait"}"><div class="small">${i+1} · ${esc(owners[byId[id].actor])}</div><strong>${esc(id)}</strong><div class="small">${esc(selectedIds.has(id)?human(byId[id].tool):"Wait for review")}</div></div>`).join("")}</div><p class="small">Competing requests are desired changes, not new authority. Existing actor approvals and exact batch consent are checked before execution.</p></div><div class="grid g2"><div class="card tablewrap"><h2>Why this order helps</h2><table><thead><tr><th>Measure</th><th>FIFO rehearsal</th><th>Reviewed order</th></tr></thead><tbody>${[["Selected requests",compare.fifo.accepted.length,choice.accepted.length],["Priority score",compare.fifo.objective[0],choice.objective[0]],["Planned commitments",compare.fifo.committed_units,choice.committed_units],["Planned limit",compare.fifo.capacity_limit,choice.capacity_limit]].map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join("")}</tr>`).join("")}</tbody></table><p class="small">FIFO is a counterfactual policy rehearsal; it did not change another service. Priorities are explicit fixture inputs, with a capped age bonus.</p></div><div class="card"><h2>Saved service outcome</h2><p class="coordfacts">${before} initial → ${completed?.metrics?.committed??"pending"} after execution → ${s.metrics.committed} after recovery, within ${s.metrics.limit} fixture units.</p><p>Candidate traffic ${s.actual_at_outcome.candidate_percent}% · owner ${esc(s.actual_at_outcome.route_owner)}.</p><p class="small">C dependencies: ${esc(JSON.stringify(s.policy_snapshot.state.deployments["candidate-v2"].dependencies))}</p><p class="small">${s.teardown?.all_workers_stopped?"Separate teardown confirmed owned worker exits. Policy allocations above describe the captured outcome.":"No completed teardown record is available yet."}</p>${evidence("Approval and exact execution",{approval:p.approval,completed,scope:p.scope})}</div></div><div class="card"><h2>Requests that must wait</h2>${choice.waiting.length?choice.waiting.map(r=>`<div class="callout warning"><strong>${esc(r.id)} · ${esc(human(r.retry_now_code))}</strong><p>${esc(r.next_step)}</p>${evidence("All recorded constraints",r.blocking_facts)}</div>`).join(""):'<p>All requests in this plan are eligible.</p>'}</div><div class="card"><h2>What if the request were smaller?</h2><p class="small">Preview a copied request from this plan's saved initial state. The original queue and service stay unchanged. Applying a different quantity requires a new intent and exact approval.</p><div class="coordpreview"><label>Capacity request<select id="coordintent">${p.basis.intents.filter(i=>i.tool==="reserve_capacity").map(i=>`<option value="${esc(i.id)}">${esc(i.id)} · ${i.parameters.units} units</option>`).join("")}</select></label><label>Hypothetical units<input id="coordunits" type="number" min="1" max="1000" value="5"></label><button id="coordpreview" ${s.historical_source?"disabled":""}>Preview copied request</button></div><div id="coordpreviewresult" aria-live="polite"></div></div><details><summary>Conflict edges and durable execution evidence</summary><div class="card">${evidence("Shared resources",compare.conflicts)}${evidence("Registered requests",s.intents)}${evidence("Execution and reconciliation receipts",s.coordination_events)}${evidence("Planner attempts and usage",{calls:s.planner_calls,usage:s.usage})}<button id="coordreplay">Inspect policy journal replay</button><div id="coordreplaybody"></div></div></details>`;
}
async function coordinationView(ticket){
 choose("coordination");coordinationData=null;
 $("#content").innerHTML=title("Multi-agent coordination","Choose a safe order before agents act.","Compare competing deployment, cost and traffic requests. Rehearse the order, review exact effects, and recover without removing another owner's work.","Coordination lab")+`<div class="sessioncontrols"><label>Saved run<select id="coordrun">${coordinationOptions("coordination")||'<option value="">No coordination runs yet</option>'}</select></label><button id="startcoord" ${catalog.lab?.enabled&&catalog.lab?.available?.coordination&&!coordinationBusy()?"":"disabled"}>Run free coordination demo</button></div><p class="small">Fixed five-request example; real local workers and HTTP, fixture actors and capacity. Demo workers stop after the saved outcome. Live ordering and exact manager consent use the terminal.</p><div role="status">${coordinationJob()}</div><div id="coordbody"><div class="empty"><h2>Coordinate competing changes</h2><p>The free example compares 120 orders. Explore what a smaller request changes with a read-only counterfactual preview.</p></div></div>`;
 if(selected.coordination){const data=await api(`/api/run?kind=coordination&id=${encodeURIComponent(selected.coordination)}`);if(ticket!==generation||tab!=="coordination")return;coordinationPaint(data);}
 if(ticket===generation&&tab==="coordination"&&coordinationBusy())coordinationTimer=setTimeout(()=>pollCoordination(ticket,"coordination"),2000);
}
async function coordinationBenchmark(ticket){
 choose("coordination_benchmark");
 $("#content").innerHTML=title("Ordering evaluation","Measure the proposed order against a bounded reference.","Twelve transparent policy-only cases. Model ordering quality is separate from the controller's filtering and real service recovery tests.","No workers in this benchmark")+`<div class="sessioncontrols"><label>Campaign<select id="coordbenchrun">${coordinationOptions("coordination_benchmark")||'<option value="">No campaigns yet</option>'}</select></label><button id="startcoordbench" ${catalog.lab?.enabled&&catalog.lab?.available?.coordination_benchmark&&!coordinationBusy()?"":"disabled"}>Run 12 free scheduling cases</button></div><div role="status">${coordinationJob()}</div><div id="coordbenchbody"></div>`;
 if(selected.coordination_benchmark){const d=await api(`/api/run?kind=coordination_benchmark&id=${encodeURIComponent(selected.coordination_benchmark)}`);if(ticket!==generation||tab!=="coordination_benchmark")return;const s=d.summary;
 $("#coordbenchbody").innerHTML=`<div class="pillrow">${badge(s.mode,"info")}${badge(human(s.status),"info")}</div><div class="grid g4">${metric("Optimal orders",`${s.optimal} / ${s.selected}`,"All selected remain in denominator")}${metric("Valid proposals",s.valid_proposals,`${s.invalid_or_unknown} invalid/unknown; ${s.not_run} not run`)}${metric("Priority regret",s.total_priority_regret,"Difference from the explicit bounded objective")}${metric("Paid attempts",s.model_calls,`${s.missing_usage_calls} without usage`)}</div><div class="callout">Synthetic policy fixtures. No worker or service effects and no HTTP availability measurement. The free baseline tests the implementation; live Nemotron proposals require a separate bounded terminal run.</div><div class="card tablewrap"><table><thead><tr><th>Case</th><th>Status</th><th>Optimal</th><th>Priority regret</th><th>Attempts</th></tr></thead><tbody>${d.results.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.status)}</td><td>${esc(r.objective_optimal)}</td><td>${esc(r.priority_regret??"Unknown")}</td><td>${r.model_calls}</td></tr>`).join("")}</tbody></table></div>`;}
 if(ticket===generation&&tab==="coordination_benchmark"&&coordinationBusy())coordinationTimer=setTimeout(()=>pollCoordination(ticket,"coordination_benchmark"),2000);
}
async function pollCoordination(ticket,kind){if(ticket!==generation||tab!==kind)return;try{const next=await api("/api/catalog");if(ticket!==generation||tab!==kind)return;catalog=next;const j=catalog.lab?.job;if(j?.kind===kind&&j.status==="COMPLETED"&&coordinationHandledJob!==j.id){coordinationHandledJob=j.id;selected[kind]=j.result.run;}await render();}catch(err){notice(err.message);}}
document.addEventListener("click",async e=>{
 const button=e.target.closest("button");if(!button)return;
 if(button.id==="startcoord"||button.id==="startcoordbench"){
  const kind=button.id==="startcoord"?"coordination":"coordination_benchmark";if(button.disabled||tab!==kind)return;button.disabled=true;
  try{const data=await api("/api/jobs",{method:"POST",headers:{"Content-Type":"application/json","X-Rehearsal-Token":LAB_TOKEN},body:JSON.stringify({kind})});catalog.lab.job=data.job;await render();}catch(err){notice(err.message);button.disabled=false;}
 }else if(button.id==="coordpreview"&&tab==="coordination"&&coordinationData&&!button.disabled){
  const ticket=generation,p=coordinationData.summary.plans.at(-1),units=Number($("#coordunits").value);if(!Number.isInteger(units)||units<1||units>1000){notice("Use 1-1000 integer units for the copied request.");return;}button.disabled=true;
  try{const data=await api("/api/coordination-preview",{method:"POST",headers:{"Content-Type":"application/json","X-Rehearsal-Token":LAB_TOKEN},body:JSON.stringify({run:coordinationData.id,plan_digest:p.plan_digest,intent_id:$("#coordintent").value,units})});if(ticket!==generation||tab!=="coordination")return;const r=data.result.selected;$("#coordpreviewresult").innerHTML=`<div class="callout"><strong>Copied request: ${data.hypothetical_units} units</strong><p>${r.accepted.length} / ${p.basis.intents.length} requests selected; priority ${r.objective[0]}; planned commitments ${r.committed_units}/${r.capacity_limit}.</p><p>Preview only. Applying this needs a new intent and exact approval.</p>${evidence("Counterfactual order and waiting reasons",r)}</div>`;}catch(err){if(ticket===generation)notice(err.message);}finally{if(ticket===generation)button.disabled=false;}
 }else if(button.id==="coordreplay"&&coordinationData)renderReplay(coordinationData,"#coordreplaybody");
});
document.addEventListener("change",async e=>{const kind=e.target.id==="coordrun"?"coordination":e.target.id==="coordbenchrun"?"coordination_benchmark":null;if(kind){selected[kind]=e.target.value;await render();}});
'''
